/* =============================================================================
 * Family Math Night kit — page controller (vanilla ES module, no build step)
 * -----------------------------------------------------------------------------
 * Picks a unit, loads kit/unit-N.json (stations + QR paths, generated by
 * tools/generate-math-night-kit.mjs from pages that already exist on the site),
 * and lays the kit out as print sheets: plan, volunteer script, six station
 * signs, and a family passport. English leads; Spanish sits under it.
 *
 * Nothing is inserted as HTML. Every string lands through textContent, and the
 * only SVG is built with createElementNS from numbers and a path string the
 * generator produced.
 * ========================================================================== */

import {
  CHROME,
  GROUND_RULES,
  MATERIALS,
  PARTS,
  PASSPORT,
  ROLES,
  RUN_OF_SHOW,
  SETUP,
  UNIT_NAMES_ES,
  VOLUNTEER,
} from "./math-night-copy.js";

const UNITS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
const SVG_NS = "http://www.w3.org/2000/svg";
const SITE_HOST = "eduwonderlab.com";

const byId = (id) => document.getElementById(id);
const el = {
  form: byId("mn-form"),
  unit: byId("mn-unit"),
  date: byId("mn-date"),
  time: byId("mn-time"),
  place: byId("mn-place"),
  parts: byId("mn-parts"),
  print: byId("mn-print"),
  status: byId("mn-status"),
  kit: byId("kit"),
};

const state = { unit: readUnit(), kit: null, parts: new Set(PARTS.map((p) => p.id)) };

function readUnit() {
  const n = Number(new URLSearchParams(location.search).get("unit"));
  return UNITS.includes(n) ? n : 1;
}

/* ------------------------------------------------------------------ DOM ---*/

function node(tag, className, text) {
  const n = document.createElement(tag);
  if (className) n.className = className;
  if (text != null) n.textContent = text;
  return n;
}

/** An English line with its Spanish sibling right under it. */
function bi(tag, pair, className) {
  const wrap = node(tag, className);
  wrap.appendChild(node("span", "en", pair.en));
  const es = node("span", "es", pair.es);
  es.lang = "es";
  wrap.appendChild(es);
  return wrap;
}

function biList(tag, items) {
  const list = node(tag, "mn-list");
  for (const item of items) list.appendChild(bi("li", item));
  return list;
}

function checkList(items) {
  const list = node("ul", "mn-checklist");
  for (const item of items) {
    const li = node("li");
    li.appendChild(node("span", "mn-box"));
    li.lastChild.setAttribute("aria-hidden", "true");
    li.appendChild(bi("span", item, "mn-check-text"));
    list.appendChild(li);
  }
  return list;
}

function sheet(id, className) {
  const s = node("section", `mn-sheet ${className || ""}`.trim());
  s.dataset.part = id;
  return s;
}

function qrSvg(qr, label) {
  const svg = document.createElementNS(SVG_NS, "svg");
  svg.setAttribute("viewBox", `0 0 ${qr.size} ${qr.size}`);
  svg.setAttribute("class", "mn-qr");
  svg.setAttribute("role", "img");
  svg.setAttribute("aria-label", label);
  svg.setAttribute("shape-rendering", "crispEdges");
  const bg = document.createElementNS(SVG_NS, "rect");
  bg.setAttribute("width", qr.size);
  bg.setAttribute("height", qr.size);
  bg.setAttribute("fill", "#fff");
  const path = document.createElementNS(SVG_NS, "path");
  path.setAttribute("d", qr.d);
  path.setAttribute("fill", "#000");
  svg.append(bg, path);
  return svg;
}

const unitNameEs = (unit) => UNIT_NAMES_ES[unit] || "";

function shortUnitLine(kit) {
  return {
    en: `Unit ${kit.unit}: ${kit.unitName}`,
    es: `Unidad ${kit.unit}: ${unitNameEs(kit.unit)}`,
  };
}

function unitLine(kit) {
  return {
    en: `${CHROME.night.en} · ${CHROME.gradeLine.en} · Unit ${kit.unit}: ${kit.unitName}`,
    es: `${CHROME.night.es} · ${CHROME.gradeLine.es} · Unidad ${kit.unit}: ${unitNameEs(kit.unit)}`,
  };
}

function shortLink(href) {
  return `${SITE_HOST}${href}`;
}

function eventLine() {
  return [el.date.value, el.time.value, el.place.value]
    .map((v) => v.trim())
    .filter(Boolean)
    .join(" · ");
}

/* ------------------------------------------------------------- the sheets -*/

function sheetHeader(kit, title, withEvent = false) {
  const head = node("header", "mn-sheet-head");
  head.appendChild(bi("p", unitLine(kit), "mn-kicker"));
  head.appendChild(bi("h2", title));
  const when = eventLine();
  if (when && withEvent) head.appendChild(node("p", "mn-event", when));
  return head;
}

function planSheets(kit) {
  const out = [];

  const plan = sheet("plan");
  plan.appendChild(
    sheetHeader(kit, { en: "Plan for the night", es: "Plan para la noche" }, true),
  );
  plan.appendChild(bi("h3", { en: "Ground rules", es: "Reglas de la noche" }));
  plan.appendChild(biList("ul", GROUND_RULES));
  plan.appendChild(bi("h3", { en: "60-minute run of show", es: "Plan de 60 minutos" }));
  const table = node("table", "mn-table");
  const caption = node("caption", "mn-sr");
  caption.textContent = "60-minute run of show / Plan de 60 minutos";
  table.appendChild(caption);
  const body = node("tbody");
  for (const step of RUN_OF_SHOW) {
    const tr = node("tr");
    tr.appendChild(node("th", "mn-time", `${step.start}–${step.start + step.minutes} min`));
    const td = node("td");
    td.appendChild(bi("strong", step.title, "mn-step-title"));
    td.appendChild(bi("span", step.body, "mn-step-body"));
    tr.appendChild(td);
    body.appendChild(tr);
  }
  table.appendChild(body);
  plan.appendChild(table);
  out.push(plan);

  const setup = sheet("plan");
  setup.appendChild(
    sheetHeader(kit, { en: "Materials and set-up", es: "Materiales y preparación" }),
  );
  setup.appendChild(bi("h3", { en: "Materials", es: "Materiales" }));
  setup.appendChild(checkList(MATERIALS));
  setup.appendChild(bi("h3", { en: "Set-up checklist", es: "Lista de preparación" }));
  for (const group of SETUP) {
    setup.appendChild(bi("h4", group.when, "mn-when"));
    setup.appendChild(checkList(group.items));
  }
  out.push(setup);

  const index = sheet("plan");
  index.appendChild(sheetHeader(kit, { en: "The six stations", es: "Las seis estaciones" }));
  index.appendChild(bi("p", CHROME.testQr, "mn-note"));
  const stations = node("ol", "mn-station-index");
  kit.stations.forEach((s) => {
    const li = node("li");
    li.appendChild(qrSvg(s.qr, `QR code: ${s.title}`));
    const text = node("div");
    text.appendChild(bi("strong", ROLES[s.role].name));
    text.appendChild(node("span", "mn-station-title", s.title));
    text.appendChild(node("span", "mn-station-link", shortLink(s.href)));
    li.appendChild(text);
    stations.appendChild(li);
  });
  index.appendChild(stations);
  out.push(index);
  return out;
}

function scriptSheet(kit) {
  const s = sheet("script");
  s.appendChild(sheetHeader(kit, VOLUNTEER.heading));
  s.appendChild(bi("p", VOLUNTEER.lead, "mn-note"));
  for (const part of [VOLUNTEER.welcome, VOLUNTEER.station, VOLUNTEER.closing]) {
    s.appendChild(bi("h3", part.title));
    s.appendChild(biList("ul", part.lines));
  }
  return s;
}

function lessonLine(kit, ids) {
  const wanted = ids.filter((id) => kit.lessonTitles[id]);
  if (!wanted.length) return null;
  const en = wanted.map((id) => `${CHROME.lessonWord.en} ${id}: ${kit.lessonTitles[id].en}`);
  const es = wanted.map(
    (id) => `${CHROME.lessonWord.es} ${id}: ${kit.lessonTitles[id].es || kit.lessonTitles[id].en}`,
  );
  return { en: en.join(" · "), es: es.join(" · ") };
}

function signSheet(kit, station, index) {
  const role = ROLES[station.role];
  const s = sheet("signs", "mn-sign");
  s.appendChild(
    bi(
      "p",
      {
        en: CHROME.stationOf.en(index + 1, kit.stations.length),
        es: CHROME.stationOf.es(index + 1, kit.stations.length),
      },
      "mn-kicker",
    ),
  );
  s.appendChild(bi("h2", role.name, "mn-sign-role"));
  s.appendChild(node("p", "mn-sign-title", station.title));
  s.appendChild(bi("p", unitLine(kit), "mn-unit-line"));
  const lessons = lessonLine(kit, station.lessons);
  if (lessons) {
    const p = node("p", "mn-connects");
    p.appendChild(bi("span", CHROME.connects, "mn-connects-label"));
    p.appendChild(bi("span", lessons));
    s.appendChild(p);
  }
  s.appendChild(bi("h3", CHROME.atTable));
  s.appendChild(biList("ol", role.steps));
  s.appendChild(bi("h3", CHROME.tryAsking));
  s.appendChild(biList("ul", role.ask));

  const scan = node("div", "mn-scan");
  scan.appendChild(qrSvg(station.qr, `QR code: ${station.title}`));
  const scanText = node("div", "mn-scan-text");
  scanText.appendChild(bi("p", CHROME.scan, "mn-scan-label"));
  scanText.appendChild(node("p", "mn-short", shortLink(station.href)));
  scan.appendChild(scanText);
  s.appendChild(scan);
  s.appendChild(bi("p", CHROME.calm, "mn-calm"));
  return s;
}

function passportSheet(kit) {
  const s = sheet("passport", "mn-passport-sheet");
  for (let copy = 0; copy < 2; copy++) {
    const card = node("article", "mn-passport");
    card.appendChild(bi("p", shortUnitLine(kit), "mn-kicker"));
    card.appendChild(bi("h2", PASSPORT.title));
    const when = eventLine();
    if (when) card.appendChild(node("p", "mn-event", when));
    card.appendChild(bi("p", PASSPORT.lead, "mn-note"));
    const grid = node("ol", "mn-stamps");
    kit.stations.forEach((station) => {
      const li = node("li", "mn-stamp");
      li.appendChild(bi("strong", ROLES[station.role].name));
      li.appendChild(node("span", "mn-stamp-title", station.title));
      const box = node("span", "mn-stamp-box");
      box.appendChild(bi("span", PASSPORT.stamp, "mn-stamp-hint"));
      li.appendChild(box);
      grid.appendChild(li);
    });
    card.appendChild(grid);
    card.appendChild(bi("p", PASSPORT.noticed, "mn-noticed"));
    const home = kit.stations.find((x) => x.role === "studio") || kit.stations[0];
    const foot = node("div", "mn-passport-foot");
    foot.appendChild(qrSvg(home.qr, `QR code: ${home.title}`));
    const footText = node("div");
    footText.appendChild(bi("p", PASSPORT.home));
    footText.appendChild(node("p", "mn-short", shortLink(home.href)));
    foot.appendChild(footText);
    card.appendChild(foot);
    s.appendChild(card);
    if (copy === 0) s.appendChild(node("hr", "mn-cut"));
  }
  return s;
}

/* ------------------------------------------------------------- the page ---*/

function renderKit() {
  el.kit.textContent = "";
  const kit = state.kit;
  if (!kit) return;
  const sheets = [
    ...planSheets(kit),
    scriptSheet(kit),
    ...kit.stations.map((s, i) => signSheet(kit, s, i)),
    passportSheet(kit),
  ];
  for (const s of sheets) {
    s.hidden = !state.parts.has(s.dataset.part);
    el.kit.appendChild(s);
  }
}

function setStatus(message) {
  el.status.textContent = message;
}

async function loadUnit(unit) {
  try {
    const res = await fetch(`./kit/unit-${unit}.json`, { cache: "no-cache" });
    if (!res.ok) throw new Error("kit");
    const kit = await res.json();
    if (!kit || kit.unit !== unit || !Array.isArray(kit.stations)) throw new Error("kit");
    state.kit = kit;
    renderKit();
    setStatus(
      `${CHROME.ready.en(unit, kit.stations.length)} ${CHROME.ready.es(unit, kit.stations.length)}`,
    );
  } catch (_e) {
    state.kit = null;
    el.kit.textContent = "";
    setStatus(`${CHROME.loadError.en} ${CHROME.loadError.es}`);
  }
}

function buildControls() {
  for (const unit of UNITS) {
    const opt = node("option", null, String(unit));
    opt.value = String(unit);
    el.unit.appendChild(opt);
  }
  el.unit.value = String(state.unit);
  for (const part of PARTS) {
    const label = node("label", "mn-part");
    const box = node("input");
    box.type = "checkbox";
    box.value = part.id;
    box.checked = true;
    label.append(box, node("span", null, part.en));
    const es = node("span", "mn-es", part.es);
    es.lang = "es";
    label.appendChild(es);
    el.parts.appendChild(label);
    box.addEventListener("change", () => {
      if (box.checked) state.parts.add(part.id);
      else state.parts.delete(part.id);
      renderKit();
    });
  }
}

async function nameUnits() {
  // Unit names come from the generated kit files, so the picker never carries
  // a second copy of them; fall back to the bare number if one cannot load.
  await Promise.all(
    UNITS.map(async (unit) => {
      try {
        const res = await fetch(`./kit/unit-${unit}.json`);
        const kit = await res.json();
        const opt = el.unit.querySelector(`option[value="${unit}"]`);
        if (opt && kit.unitName)
          opt.textContent = `${unit} · ${kit.unitName} / ${unitNameEs(unit)}`;
      } catch (_e) {
        /* the bare number still works */
      }
    }),
  );
}

el.unit.addEventListener("change", () => {
  state.unit = Number(el.unit.value);
  try {
    const url = new URL(location.href);
    url.searchParams.set("unit", String(state.unit));
    history.replaceState(null, "", url);
  } catch (_e) {
    /* the kit still loads without a shareable address */
  }
  loadUnit(state.unit);
});

for (const input of [el.date, el.time, el.place]) input.addEventListener("input", renderKit);
el.form.addEventListener("submit", (event) => event.preventDefault());
el.print.addEventListener("click", () => window.print());

buildControls();
loadUnit(state.unit);
nameUnits();
